class LRUCache
  def initialize(capacity)
    @capacity = capacity
    @entries = {}
  end

  def get(key)
    return unless @entries.key?(key)

    @entries[key] = @entries.delete(key)
  end

  def put(key, value)
    @entries.delete(key)
    @entries[key] = value
    @entries.shift if @entries.size > @capacity
    value
  end
end
